package com.bank.spark.model;

// A row with its original key and a salted composite key.
public class SaltedRow {
    private final String originalKey;
    private final int salt;
    private final String payload;

    public SaltedRow(String originalKey, int salt, String payload) {
        this.originalKey = originalKey;
        this.salt = salt;
        this.payload = payload;
    }

    public String saltedKey() { return originalKey + "_" + salt; }
    public String getOriginalKey() { return originalKey; }
    public int getSalt() { return salt; }
    public String getPayload() { return payload; }
}
