package com.bank.spark.service;

import com.bank.spark.model.SaltedRow;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.Random;
import java.util.TreeMap;

// Salts the hot key on the large side and explodes the small side.
public class SaltingJoiner {

    private final int saltFactor;
    private final Random random = new Random(42);

    public SaltingJoiner(int saltFactor) {
        this.saltFactor = saltFactor;
    }

    // Large side: assign a random salt 0..N-1 to each hot-key row.
    public List<SaltedRow> saltLargeSide(String hotKey, int rows) {
        List<SaltedRow> out = new ArrayList<>();
        for (int i = 0; i < rows; i++) {
            int salt = random.nextInt(saltFactor);
            out.add(new SaltedRow(hotKey, salt, "txn" + i));
        }
        return out;
    }

    // Small side: explode the single account row into N salted copies.
    public List<SaltedRow> explodeSmallSide(String hotKey, String accountPayload) {
        List<SaltedRow> out = new ArrayList<>();
        for (int salt = 0; salt < saltFactor; salt++) {
            out.add(new SaltedRow(hotKey, salt, accountPayload));
        }
        return out;
    }

    // Report how the hot key's rows now spread across salted partitions.
    public Map<Integer, Long> partitionSpread(List<SaltedRow> largeSalted) {
        Map<Integer, Long> spread = new TreeMap<>();
        for (SaltedRow r : largeSalted) {
            spread.merge(r.getSalt(), 1L, Long::sum);
        }
        return spread;
    }

    public int getSaltFactor() { return saltFactor; }
}
