package com.bank.spark;

import com.bank.spark.model.SaltedRow;
import com.bank.spark.service.SaltingJoiner;

import java.util.List;
import java.util.Map;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class SaltingDemo {

    private static final Logger log = Logger.getLogger(SaltingDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        handler.setLevel(Level.ALL);
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        int saltFactor = 4;
        SaltingJoiner joiner = new SaltingJoiner(saltFactor);
        String hotKey = "SAV2001";

        log.warning(() -> "Before salting: hot key " + hotKey + " -> all 2,000,000 rows in ONE partition (straggler)");

        // Salt the large side (use 2000 rows to represent the millions).
        List<SaltedRow> largeSalted = joiner.saltLargeSide(hotKey, 2000);
        Map<Integer, Long> spread = joiner.partitionSpread(largeSalted);
        log.info(() -> "After salting with factor " + saltFactor + ", hot key spread across partitions: " + spread);

        // Explode the small side so the join still matches.
        List<SaltedRow> smallExploded = joiner.explodeSmallSide(hotKey, "Account:Rajesh pooling");
        log.info(() -> "Small side account row duplicated " + smallExploded.size() + " times (one per salt): TRADE-OFF");

        // Each salted large row finds its account copy by salted key — balanced join.
        long matched = largeSalted.stream()
                .filter(l -> smallExploded.stream().anyMatch(s -> s.saltedKey().equals(l.saltedKey())))
                .count();
        log.info(() -> "Matched " + matched + " of " + largeSalted.size() + " salted rows (join still correct)");

        log.info("Result: one straggler partition became " + saltFactor
                + " balanced partitions; cost = " + saltFactor + "x copies of the hot account row.");
    }
}

